<x-table :rows="$items" caption="Waste lines" :empty-title="$search?'No matching waste lines':'No waste lines yet'" empty-description="Add ingredients to a draft waste record."><x-slot:toolbar><div class="unit-toolbar"><button class="btn btn-sm btn-success" data-bs-toggle="offcanvas" data-bs-target="#createStockWasteItemDrawer" aria-label="Add waste line"><i class="bi bi-plus-lg"></i></button><x-search-filter :action="route('stock-waste-items.index')" search-label="Search waste lines" search-placeholder="Search ingredient" search-container-class="unit-search-field" class="unit-search-filter" data-live-search="true" data-live-target="#stock-waste-item-results" data-live-delay="300" submit-label="Filter" :search-value="$search" :preserve="$wasteId?['stock_waste_id']:[]" /></div></x-slot:toolbar><x-slot:head><tr><th>Waste</th><th>Ingredient</th><th class="text-end">Quantity</th><th>Unit</th><th class="text-end">Unit cost</th><th class="text-end">Total cost</th><th class="text-end">Actions</th></tr></x-slot:head><x-slot:body>@foreach($items as $i)<tr><td>{{ $i->stockWaste?->waste_number }}</td><td>{{ $i->ingredient?->name }}</td><td class="text-end">{{ number_format((float)$i->quantity,3) }}</td><td>{{ $i->unit?->abbreviation }}</td><td class="text-end">{{ number_format((float)$i->unit_cost,6) }}</td><td class="text-end">{{ number_format((float)$i->total_cost,2) }}</td><td class="text-end">@if($i->stockWaste?->status==='draft')<button class="btn btn-sm btn-outline-primary" data-bs-toggle="offcanvas" data-bs-target="#editStockWasteItemDrawer-{{ $i->id }}" aria-label="Edit waste line"><i class="bi bi-pencil"></i></button><x-confirm-delete :action="route('stock-waste-items.destroy',$i).($wasteId?'?stock_waste_id='.$wasteId:'')" title="Delete waste line?" button-aria-label="Delete waste line"><i class="bi bi-trash"></i></x-confirm-delete>@endif</td></tr>@endforeach</x-slot:body></x-table><div data-live-edit-drawers>@include('stock-waste-items.partials.edit-drawers')</div>
